By Council Member
Awards from individual Council Members to arts and cultural organizations represent the largest share of awards by Council Member, 41.7% ($29,808,219), but not the majority.
30.8% ($22,026,034) of arts and culture awards do not have a Council Member associated with them (Council Member: NA) at all. 27% ($19,269,000) of awards come from the Council Speaker (Council Member: Speaker).
The remaining 0.5% ($381,488) is awarded by the five Borough Delegations.


Code
d3 = require("d3@7")
groups = transpose(cm_data)

// Based on https://gist.github.com/dbuezas/9306799
chart = {
  const width = 760, height = 440;
  const radius = Math.min(width * 0.34, height / 2 - 20);

  const svg = d3.create("svg")
      .attr("viewBox", [-width / 2, -height / 2, width, height])
      .attr("style", "max-width: 100%; height: auto; font: 13px Authentic Sans;");

  const color = d3.scaleOrdinal()
      .domain(["Individual CMs", "No CM listed", "Speaker", "Borough Delegations"])
      .range(["#3258a3", "#3e7bd2", "#73b3e7", "#c7e1f6"])
      .unknown("#8a8a8a");

  const arc      = d3.arc().innerRadius(0).outerRadius(radius * 0.8);
  const outerArc = d3.arc().innerRadius(radius * 0.9).outerRadius(radius * 0.9);
  const midAngle = d =&gt; d.startAngle + (d.endAngle - d.startAngle) / 2;
  const arcs = d3.pie().sort(null).value(d =&gt; d.pct)(groups);

  // label anchor per slice, plus a de-overlap pass the gist doesn't have
  const labels = arcs.map(d =&gt; {
    const side = midAngle(d) &lt; Math.PI ? 1 : -1;
    return { d, side, y: outerArc.centroid(d)[1], x: radius * side };
  });

  const minGap = 34;
  for (const side of [1, -1]) {
    const col = labels.filter(l =&gt; l.side === side).sort((a, b) =&gt; a.y - b.y);
    for (let i = 1; i &lt; col.length; i++)
      col[i].y = Math.max(col[i].y, col[i - 1].y + minGap);
    const overflow = col.length ? col[col.length - 1].y - (height / 2 - 20) : 0;
    if (overflow &gt; 0) col.forEach(l =&gt; l.y -= overflow);
  }

  svg.append("g")
    .selectAll("path")
    .data(labels)
    .join("path")
      .attr("d", l =&gt; arc(l.d))
      .attr("fill", l =&gt; color(l.d.data["Council Member"]))
      .attr("stroke", "white")
      .attr("stroke-width", 2)
    .append("title")
      .text(l =&gt; `${l.d.data["Council Member"]}: ${l.d.data.pct.toFixed(1)}%`);

  svg.append("g")
      .attr("fill", "none")
      .attr("stroke", "#666")
      .attr("stroke-width", 1)
      .attr("opacity", 0.5)
    .selectAll("polyline")
    .data(labels)
    .join("polyline")
      .attr("points", l =&gt; [
        arc.centroid(l.d),
        outerArc.centroid(l.d),
        [l.x * 0.95, l.y]
      ]);

  svg.append("g")
    .selectAll("text")
    .data(labels)
    .join("text")
      .attr("transform", l =&gt; `translate(${l.x},${l.y})`)
      .attr("text-anchor", l =&gt; l.side === 1 ? "start" : "end")
      .attr("dy", "0.35em")
      .call(t =&gt; t.append("tspan")
          .attr("font-weight", "bold")
          .text(l =&gt; l.d.data["Council Member"]))
      .call(t =&gt; t.append("tspan")
          .attr("x", 0).attr("dy", "1.2em")
          .attr("fill", "#555")
          .text(l =&gt; `${l.d.data.pct.toFixed(1)}%`));

  return svg.node();
}























The amount of money awarded to arts and cultural organizations by individual council member varies widely.
Council Member Marte made 77 awards to arts and cultural organizations, totalling $902,000.
Council Member Nurse made only 4 awards to arts and cultural organizations, totalling $45,000.



