groups_2 = transpose(agency_data)

agencyChart = {
  const width = 760, height = 460;
  const radius = Math.min(width * 0.34, height / 2 - 20);

  const svg = d3.create("svg")
      .attr("viewBox", [-width / 2, -height / 2, width, height])
      .attr("style", "max-width: 100%; height: auto; font: 13px Authentic Sans;");

  // Same endpoints as the Council Member pie, spread across however many rows
  // agency_data has. Lab interpolation keeps the lightness steps even.
  const ramp = d3.interpolateLab("#3258a3", "#c7e1f6");
  const n = groups_2.length;
  const color = d3.scaleOrdinal()
      .domain(groups_2.map(d =&gt; d.Agency))
      .range(groups_2.map((_, i) =&gt; ramp(n === 1 ? 0 : i / (n - 1))))
      .unknown("#8a8a8a");

  const arc      = d3.arc().innerRadius(0).outerRadius(radius * 0.8);
  const outerArc = d3.arc().innerRadius(radius * 0.9).outerRadius(radius * 0.9);
  const midAngle = d =&gt; {
    const a = (d.startAngle + (d.endAngle - d.startAngle) / 2) % (2 * Math.PI);
    return a &lt; 0 ? a + 2 * Math.PI : a;
  };
  const rotate = -Math.PI / 4;
  const arcs = d3.pie()
      .sort(null)
      .startAngle(rotate)
      .endAngle(rotate + 2 * Math.PI)
      .value(d =&gt; d.pct)(groups_2);

  const labels = arcs.map(d =&gt; {
    const side = midAngle(d) &lt; Math.PI ? 1 : -1;
    return { d, side, y: outerArc.centroid(d)[1], x: radius * side };
  });

  const minGap = 34;
  for (const side of [1, -1]) {
    const col = labels.filter(l =&gt; l.side === side).sort((a, b) =&gt; a.y - b.y);
    for (let i = 1; i &lt; col.length; i++)
      col[i].y = Math.max(col[i].y, col[i - 1].y + minGap);
    const overflow = col.length ? col[col.length - 1].y - (height / 2 - 20) : 0;
    if (overflow &gt; 0) col.forEach(l =&gt; l.y -= overflow);
  }

  svg.append("g")
    .selectAll("path")
    .data(labels)
    .join("path")
      .attr("d", l =&gt; arc(l.d))
      .attr("fill", l =&gt; color(l.d.data.Agency))
      .attr("stroke", "white")
      .attr("stroke-width", 2)
    .append("title")
      .text(l =&gt; `${l.d.data.Agency}: ${l.d.data.pct.toFixed(1)}%`);

  svg.append("g")
      .attr("fill", "none")
      .attr("stroke", "#666")
      .attr("stroke-width", 1)
      .attr("opacity", 0.5)
    .selectAll("polyline")
    .data(labels)
    .join("polyline")
      .attr("points", l =&gt; [
        arc.centroid(l.d),
        outerArc.centroid(l.d),
        [l.x * 0.98, l.y]
      ]);

  svg.append("g")
    .selectAll("text")
    .data(labels)
    .join("text")
      .attr("transform", l =&gt; `translate(${l.x},${l.y})`)
      .attr("text-anchor", l =&gt; l.side === 1 ? "start" : "end")
      .attr("dy", "0.35em")
      .call(t =&gt; t.append("tspan")
          .attr("font-weight", "bold")
          .text(l =&gt; l.d.data.Agency))
      .call(t =&gt; t.append("tspan")
          .attr("x", 0).attr("dy", "1.2em")
          .attr("fill", "#555")
          .text(l =&gt; `${l.d.data.pct.toFixed(1)}%`));

  return svg.node();
}
















